<?php require_once __DIR__.'/../_bootstrap.php';admin();$d=body();required($d,['user_id','status']);if(!in_array($d['status'],['active','suspended']))fail('Invalid status.');$q=db()->prepare('UPDATE users SET status=? WHERE id=? AND role="seller"');$q->execute([$d['status'],$d['user_id']]);if(!$q->rowCount())fail('Seller not found.',404);out(['success'=>true,'message'=>'User status updated.']);
